import{reflexLabels,synapseState,reactionTrials,rulerScale}from './neural-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const nt=(x,y,s,size=18)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${esc(s)}</text>`;
export const neuralSVG=(art,label)=>`<svg class="shell-diagram neural-diagram" viewBox="0 0 560 400" role="img" aria-label="${esc(label)}">${art}</svg>`;
export const neuralTable=(rows,heads)=>'<table class="photo-data neural-data"><thead><tr>'+heads.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
export function neuralFigure(w={}){let k=w.kind||'neuron',s=w.state||'normal',body='',caption=w.result||'Symbolic sizes and timing; use the labels.';
if(k==='data')return neuralTable(Object.entries(reactionTrials).map(([c,a])=>[c,...a.map((x,i)=>i<(w.runs?.[c]??3)?x:'—')]),['Condition','Repeat1/ms','Repeat2/ms','Repeat3/ms'])+'<p class="diagram-caption">Original simulated observations, not measured personal reaction times.</p>';
if(k==='graph'){let points=w.points||[];body='<path d="M80 45V310H500" fill="none" stroke="#c3d8d6" stroke-width="3"/>';for(let y of[0,50,100,150,200,250])body+=nt(50,315-y,String(y),16)+`<path d="M80 ${310-y}h420" stroke="#b7cdcb33"/>`;for(let i=0;i<2;i++){let n=Number(points[i]);if(points[i]!==''&&points[i]!==undefined&&Number.isFinite(n)&&n>=0&&n<=250)body+=`<circle cx="${210+i*200}" cy="${310-n}" r="8" fill="#edab94"/>`;body+=nt(210+i*200,345,i?'Distraction':'Quiet',19);}body+=nt(280,28,'Mean reaction time / ms',22)+nt(280,385,'Condition',19);}
else if(k==='ruler'){body='<rect x="235" y="50" width="80" height="285" rx="9" fill="#d9c29c"/>';for(let i=0;i<=25;i+=5)body+=`<path d="M235 ${70+i*10}h20" stroke="#294355"/>`+`<text x="270" y="${76+i*10}" fill="#182e44" font-size="16">${i}</text>`;body+='<path d="M155 260h75m90 0h75" stroke="#efbd9f" stroke-width="20" stroke-linecap="round"/>'+nt(420,110,'Catch at',20)+nt(420,140,'the fingers',20)+nt(110,80,'cm',20);caption='Supplied scale: '+rulerScale.map(([d,t])=>d+'cm≈'+t+'ms').join(' · ');}
else if(k==='control'){let val=w.value??(s==='below'?2:s==='above'?8:5),y=310-val*25;body='<path d="M125 60v250h320" stroke="#b6cece" stroke-width="3" fill="none"/><path d="M125 185h320" stroke="#d4b98e" stroke-width="3" stroke-dasharray="8 5"/>'+nt(300,165,'Generic target 5',20)+`<circle cx="300" cy="${y}" r="14" fill="#edab94"/>`+nt(300,350,'Value '+Math.round(val*10)/10+' · arbitrary units',21)+nt(280,35,'Correction towards an optimum',24);}
else if(k==='reflex'){let pos=[[80,90],[240,90],[400,90],[460,190],[400,290],[240,290],[80,290]],n=Math.min(6,w.step??(s==='motor'?5:s==='sensory'?1:0));for(let i=0;i<pos.length;i++){let[x,y]=pos[i];if(i<pos.length-1)body+=`<path d="M${x} ${y}L${pos[i+1][0]} ${pos[i+1][1]}" stroke="#b8d0d2" stroke-width="3"/>`;body+=`<rect x="${x-65}" y="${y-28}" width="130" height="56" rx="16" fill="${i===n?'#ba967e':'#35536a'}" stroke="#b9cfce"/>`+(reflexLabels[i].includes('neurone')?nt(x,y-3,reflexLabels[i].split(' ')[0],20)+nt(x,y+19,'neurone',20):nt(x,y+7,reflexLabels[i],20));}caption='Illustrated spinal arc; electrical impulses along neurones, chemical junctions at synapses.';}
else if(k==='synapse'){let phase=w.step??(s==='along'?0:s==='across'?3:5),f=synapseState({step:phase,release:s!=='release-off',receptor:s!=='receptor-off'});body='<path d="M30 105h150q80 0 80 90t-80 90H30" fill="#a6c4bf44" stroke="#bdd4d0" stroke-width="4"/><path d="M530 105H380q-80 0-80 90t80 90h150" fill="#d4af9933" stroke="#e3c1a8" stroke-width="4"/>'+nt(135,55,'Sending ending',21)+nt(425,55,'Receiving membrane',21)+nt(280,345,'Enlarged synaptic cleft',20);if(f.transmitter)for(let i=0;i<5;i++)body+=`<circle cx="${f.bound?295:260+i*5+(w.progress??0)*10}" cy="${145+i*24}" r="5" fill="#edd0a5"/>`;if(s!=='receptor-off')for(let i=0;i<5;i++)body+=`<path d="M310 ${140+i*25}h15v12h-15" stroke="#b8d7d9" stroke-width="4" fill="none"/>`;if(f.nextImpulse)body+='<path d="M350 195h140l-15-10m15 10l-15 10" stroke="#edcba4" stroke-width="5" fill="none"/>';caption='Electrical → chemical → electrical; next impulse '+(f.nextImpulse?'triggered':'not yet triggered')+' in this model.';}
else {body='<circle cx="110" cy="190" r="45" fill="#a2c2bf"/><path d="M150 190h280m-335-35l-40-45m40 80l-60 10m65 20l-40 50M430 190l60-50m-60 50l65 40" stroke="#b8d0cb" stroke-width="7" fill="none"/>';for(let i=0;i<5;i++)body+=`<rect x="${180+i*45}" y="170" width="30" height="40" rx="14" fill="#d3b797"/>`;body+=nt(110,90,'Cell body',21)+nt(310,270,'Axon with insulating regions',20)+nt(280,355,'Impulse direction →',23);}
return neuralSVG(body,w.title||k)+'<p class="diagram-caption">'+esc(caption)+'</p>';}
